        echo '<div data-production-drawer><h2>Add Performance</h2><p>Add exact showtimes, then review showtimes, venue and ticket prices. Decide whether ticket sales open immediately or remain closed.</p>';if(($draft['type']??'')==='schedule_ambiguity')echo '<p role="status">Some showtimes occur twice when clocks change. Choose the first or second occurrence for those showtimes.</p>';if(!$layouts){echo '<p>Publish a seating layout in Settings before scheduling.</p></div>';return;}
