??'')==='general_admission'?'selected':'').'>General admission</option></select></label><fieldset><legend>Selected showtimes</legend><div data-compact-showtimes>';if($draft){foreach($draft['input']['dates'] as $i=>$date)self::showtime((string)$date,(string)($draft['input']['times'][$i]??''),(string)($draft['input']['offsets'][$i]??''),in_array($i,$draft['ambiguous']??[],true));}else self::showtime();echo '</div><button type="button" data-add-compact-showtime>Add another date / time</button></fieldset>';
        $defaults=CommercePricingService::ready($db)&&$production?CommercePricingService::defaults($db,$org,$production):null;$inherit=($draft['input']['pricing_source']??($defaults?'production':'override'))==='production';echo '<label>Pricing source<select name="pricing_source" data-pricing-source><option value="production" '.(!$defaults?'disabled':($inherit?'selected':'')).'>Inherit '.(($defaults['source']??'production')==='organization'?'organization':'production').' defaults</option><option value="override" '.(!$inherit?'selected':'').'>Set prices for these performances</option></select></label>';
        $existing=$production?self::rows($db,'SELECT prices_json FROM commerce_performances WHERE organization_id=? AND production_id=? ORDER BY id DESC LIMIT 1',[$org,$production]):[];$prices=$draft['prices']??$defaults['prices']??($existing?json_decode($existing[0]['prices_json'],true):[]);$selectedLayout=$layouts[0];foreach($layouts as $layout)if((int)$layout['id']===(int)($draft['layout']??0))$selectedLayout=$layout;$zones=[];foreach(json_decode($selectedLayout['document_json'],true)['items'] as $item)if($item['kind']==='seat')$zones[(string)$item['zone']]=true;$zones=array_map('strval',array_keys($zones));$prices=array_intersect_key($prices,array_flip($zones));foreach($zones as $zone)if(!isset($prices[$zone]))$prices[$zone]=['Adult'=>null];self::priceEditor($prices,$zones);$terms=$draft['input']??[];echo '<fieldset class="commerce-creation-terms"><legend>Sales &amp; checkout settings</legend><label>Ticket sales<select name="initial_sales"><option value="closed" '.(($terms['initial_sales']??'closed')==='closed'?'selected':'').'>Keep sales closed</option><option value="open" '.(($terms['initial_sales']??'closed')==='open'?'selected':'').'>Open sales when performances are created</option></select></label><p>These settings apply to each showtime in this batch. You can still edit individual shows afterward.</p><div class="commerce-finance-grid">';CommerceExperience::input('fee_amount','Order fee','number',(string)($terms['fee_amount']??'0.00'),'min="0" max="1000" step="0.01" required');CommerceExperience::input('tax_percent','Tax (%)','number',(string)($terms['tax_percent']??'0.00'),'min="0" max="100" step="0.01" required');echo '</div><details class="commerce-legacy-discount"><summary>Advanced · fixed performance discount</summary><p>Optional legacy reduction applied once per performance order. Promo codes will be managed separately.</p>';CommerceExperience::input('discount_amount','Legacy order discount','number',(string)($terms['discount_amount']??'0.00'),'min="0